    rows = c.execute("select * from src.bank_risk_metrics where SECUCODE in ('601077.SH','000001.SZ')").fetchall()
    print("bank rows:", rows[:4])
except Exception as e:
    print("bank query ERR", str(e)[:200])
c.close()
