import sys
sys.stdout.reconfigure(encoding="utf-8")
import duckdb
c = duckdb.connect("data/cnequity/duckdb/cnequity.duckdb", read_only=True)
syms = ["601000.SH","600461.SH","601077.SH","601298.SH","601033.SH","000651.SZ","000001.SZ","000598.SZ","000429.SZ"]
lst = ",".join("'" + s + "'" for s in syms)
print("=== industry_members (latest sw) ===")
try:
    rows = c.execute("select symbol, industry_code, industry_name, as_of_date from industry_members where classification_system='sw' and as_of_date=(select max(as_of_date) from industry_members where classification_system='sw') and symbol in (" + lst + ")").fetchall()
    for r in rows: print(r)
except Exception as e: print("ERR", str(e)[:200])
print("=== bank_risk_metrics latest ===")
try:
    rows = c.execute("select SECUCODE, REPORT_DATE, HXYJBCZL, NONPERLOAN, BLDKBBL from bank_risk_metrics where SECUCODE in ('601077.SH','000001.SZ') order by SECUCODE, REPORT_DATE desc").fetchall()
    for r in rows[:8]: print(r)
except Exception as e: print("ERR", str(e)[:200])
print("=== roe / ocf_to_profit for 000651.SZ ===")
try:
    rows = c.execute("select report_period, item_code, item_value from financial_statement_items where symbol='000651.SZ' and item_code in ('roe','net_cash_operate','net_profit') and report_period like '%Q4' order by report_period desc limit 12").fetchall()
    for r in rows: print(r)
except Exception as e: print("ERR", str(e)[:200])
c.close()
'@; $f = Join-Path $env:TEMP 'dsh_lake_probe2.py'; [System.IO.File]::WriteAllText($f, $code, [System.Text.UTF8Encoding]::new($false)); python $f; Remove-Item $f -Force

