3: const fs = require('fs'), path = require('path'), vm = require('vm');
4: const dir = __dirname;
5: // Windows checkout 可能是 CRLF，统一成 LF 后再按行匹配主脚本
6: const html = fs.readFileSync(path.join(dir, 'index.html'), 'utf8').replace(/\r\n/g, '\n');
7: 
8: // 主脚本 = 最后一个 <script>...</script>（前面是 sql.js 与 wasm base64）
9: const m = html.match(/<script>\n\(function \(\) \{\n'use strict';\n\n\/\* =+ 常量[\s\S]*?<\/script>/);
10: if (!m) throw new Error('找不到主脚本');
11: const main = m[0].replace(/^<script>\n/, '').replace(/<\/script>$/, '');
