24: // sql.js 已改为从国内 CDN 加载（不再内联 base64）。测试时从 CDN 下载引擎与 wasm 并注入沙箱。
25: const SQLJS_BASES = [
26:   'https://cdn.staticfile.org/sql.js/1.13.0/',
27:   'https://cdn.bootcdn.net/ajax/libs/sql.js/1.13.0/',
28:   'https://cdn.jsdelivr.net/npm/sql.js@1.13.0/dist/'
29: ];
30: const _httpGet = url => new Promise((resolve, reject) => {
31:   const https = require('https');
32:   const req = https.get(url, res => {
33:     if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
34:       res.resume(); return _httpGet(res.headers.location).then(resolve, reject);
35:     }
36:     if (res.statusCode !== 200) { res.resume(); return reject(new Error('HTTP ' + res.statusCode + ' ' + url)); }
37:     const chunks = [];
38:     res.on('data', d => chunks.push(d));
39:     res.on('end', () => resolve(Buffer.concat(chunks)));
40:   });
41:   req.on('error', reject);
42:   req.setTimeout(20000, () => { req.destroy(new Error('timeout ' + url)); });
43: });
44: 
45: const sandbox = {
46:   console, Date, Math, Number, String, Object, Array, JSON, isNaN, isFinite,
47:   parseFloat, parseInt, atob: s => Buffer.from(s, 'base64').toString('binary'),
48:   setTimeout: () => 0, setInterval: () => 0, clearTimeout: () => {}, clearInterval: () => {},
49:   confirm: () => true, alert: () => {},
50:   indexedDB: { open() { return {}; } },
51:   localStorage: { getItem: () => null, setItem: () => {} },
52:   document: {
53:     getElementById: el,
54:     querySelector: s => el(s.replace(/^#/, '')),
55:     querySelectorAll: () => [],
56:     addEventListener: () => {},
57:     createElement: () => ({ style: {}, dataset: {}, remove() {}, click() {}, appendChild() {}, setAttribute() {} }),
58:     head: { appendChild() {} }, body: { appendChild() {} }
59:   },
60:   fetch: (url) => _httpGet(url).then(buf => ({
61:     ok: true,
62:     status: 200,
63:     arrayBuffer: () => Promise.resolve(buf.buffer.slice(buf.byteOffset, buf.byteOffset + buf.byteLength))
64:   })),
65:   __SQLJS_BASES__: SQLJS_BASES,
66:   location: { search: '' },
67:   FileReader: function () {},
68:   Blob: function () {}, URL: { createObjectURL: () => '', revokeObjectURL() {} }
69: };
70: sandbox.window = sandbox;
71: sandbox.self = sandbox;
72: sandbox.globalThis = sandbox;
73: vm.createContext(sandbox);
