/* 宪法时序条款判定（字段类型：number=聚合值(最近两年min/max) 或 [y1,y2] 数组，兼容两种）
   ocfd2y: OCF/分红，< ocfMin(默认1) 越线；payout2y: 支付率%，> payoutMax(默认80) 越线 */
function _mThresh(key, dflt) { return (CFG && CFG.margin && CFG.margin[key] != null) ? +CFG.margin[key] : dflt; }

tool_input.new_string:
/* ============================== 分行业择时矩阵 ==============================
   一套 margin 打天下会「银行被错杀 / 周期股买在半山腰」。CFG.margin_by_ind
   按申万一级行业覆盖全局 CFG.margin：行业参数优先，未命中回落全局。
   旧库里可能仍是短名（交运/家电/医药…），用 IND_ALIAS 归一化。
   这里只做「参数合并」，不改 _mComputeOne 的计算式；改计算口径必须同步递增
   MARGIN_CACHE_KEY 版本号，否则当天仍读到旧缓存结果。 */
const IND_ALIAS = { '交运': '交通运输', '家电': '家用电器', '医药': '医药生物',
  '公用': '公用事业', '化工': '基础化工', '保险': '非银金融' };
function getMarginParams(t) {
  const g = (CFG && CFG.margin) || {};
  const byInd = (CFG && CFG.margin_by_ind) || {};
  const ind = t && t.ind ? (IND_ALIAS[t.ind] || t.ind) : '';
  const o = (ind && byInd[ind]) || {};
  return Object.assign({}, g, o);
}
/* 行业专属风控红线：阈值写在 margin_by_ind[ind].risk，实测值在 t.risk（可选）。
   字段缺失一律「不越线」——缺数据不等于违规，绝不用假数据误杀。 */
function _rNum(v) { return (typeof v === 'number' && isFinite(v)) ? v : null; }
function _rBelow(v, lim) {
  if (lim == null) return false;
  if (Array.isArray(v)) return v.length >= 2 && v.every(x => x != null && +x < lim);
  const n = _rNum(v); return n != null && n < lim;
}
function _rAbove(v, lim) {
  if (lim == null) return false;
  if (Array.isArray(v)) return v.length >= 2 && v.every(x => x != null && +x > lim);
  const n = _rNum(v); return n != null && n > lim;
}
function indRiskFlags(t) {
  if (!t) return [];
  const p = getMarginParams(t);
  const r = p.risk || {}, d = t.risk || {};
  const out = [];
  if (t.risk_type === 'bank' || p.group === '金融') {
    if (_rBelow(d.core_tier1, r.coreTier1Min)) out.push('核心一级资本充足率 ' + fmt(d.core_tier1, 2) + '% < ' + r.coreTier1Min + '%');
    if (_rAbove(d.npl, r.nplMax)) out.push('不良率 ' + fmt(d.npl, 2) + '% > ' + r.nplMax + '%');
    if (_rBelow(d.provision, r.provisionMin)) out.push('拨备覆盖率 ' + fmt(d.provision, 0) + '% < ' + r.provisionMin + '%');
  }
  if (t.risk_type === 'consumer' || p.group === '消费医药') {
    if (_rBelow(d.roe2y, r.roeMin)) out.push('ROE 连续两年 < ' + r.roeMin + '%');
    if (_rBelow(d.ocf_to_profit, r.ocfToProfitMin)) out.push('OCF/净利 ' + fmt(d.ocf_to_profit, 0) + '% < ' + r.ocfToProfitMin + '%');
  }
  if (t.risk_type === 'cyclical' || p.group === '周期') {
    if (_rAbove(d.debt_ratio, r.debtMax)) out.push('资产负债率 ' + fmt(d.debt_ratio, 0) + '% > ' + r.debtMax + '%');
  }
  return out;
}

/* 宪法时序条款判定（字段类型：number=聚合值(最近两年min/max) 或 [y1,y2] 数组，兼容两种）
   ocfd2y: OCF/分红，< ocfMin(默认1) 越线；payout2y: 支付率%，> payoutMax(默认80) 越线
   阈值优先取该标的所属行业的覆盖值（如银行 ocfdMin=0 → OCF 判定对银行失效）。 */
function _mThresh(key, dflt, t) {
  const p = t ? getMarginParams(t) : ((CFG && CFG.margin) || {});
  return (p[key] != null) ? +p[key] : dflt;
}

