  // 宪法条款：「连续两年」OCF/分红 或 支付率 越线（用 helper 兼容 number/array 两种字段形态）
  if (ocf2yBreak(r.t))
    out.push(['bad', '×', esc(r.name) + ' OCF/分红连续两年 &lt; ' + ocfMin + '，分红非经营所得，违反宪法，建议清出。']);
  if (payout2yBreak(r.t))
