  else if (r.t.ocfd != null && r.t.ocfd < ocfMin + 0.5)
    out.push(['warn', '!', esc(r.name) + ' OCF/分红 仅 ' + fmt(r.t.ocfd, 2) + '，覆盖偏薄。']);
  // 行业专属红线（银行资本充足/不良/拨备、消费 ROE/现金含量、周期负债率等）
