  ok(P.indRiskFlags({ ind: '银行', risk_type: 'bank', risk: { core_tier1: 9.61, npl: 1.05, provision: 214.75 } }).length === 0,
    '实测平安银行三项达标 → 不误报');
  ok(P.indRiskFlags({ ind: '银行', risk_type: 'bank' }).length === 0,
    'risk 字段缺失 → 降级不误杀（缺数据≠违规）');
  ok(P.indRiskFlags({ ind: '家用电器', risk_type: 'consumer', risk: { roe2y: [7, 7], ocf_to_profit: 60 } }).length === 2,
    '消费 ROE 连续两年<8 与 OCF/净利<80 同时触发');
  ok(P.indRiskFlags({ ind: '家用电器', risk_type: 'consumer', risk: { roe2y: [20.3, 25.42], ocf_to_profit: 146.5 } }).length === 0,
    '实测格力两项达标 → 不误报');
  ok(P.indRiskFlags({ ind: '综合', risk_type: 'general' }).length === 0,
    '未分组行业无红线');

  const inds = full.targets.map(t => t.ind);
  ok(inds.every(x => x && ['交运', '家电', '医药', '公用'].indexOf(x) < 0),
    'targets 全部标记申万一级标准名（无旧短名）→ ' + inds.join('、'));
  ok(full.targets.every(t => t.risk_type), 'targets 全部带 risk_type 行业风控标签');
  const banks = full.targets.filter(t => t.risk_type === 'bank');
  ok(banks.length === 2 && banks.every(t => t.risk && t.risk.core_tier1 != null),
    '银行目标带湖内实测风控字段（' + banks.length + ' 只）');
  const cons = full.targets.filter(t => t.risk_type === 'consumer');
  ok(cons.length >= 1 && cons.every(t => t.risk && t.risk.roe2y),
    '消费目标带 ROE/现金含量实测字段（' + cons.length + ' 只）');
}

